  "elul_a.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 17c2.5-4 5-8 10-9 2.5-.5 5 1 6 3-3-1-5 0-7 2-2 2-4.5 4-9 4z\" fill=\"#d4a373\" stroke=\"#8c5828\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><path d=\"M20 11c.8 1.5.2 3.5-1.5 4.5s-3.5.2-4.5-1.5\" stroke=\"#b37b42\" stroke-width=\"1.5\" fill=\"none\"/><circle cx=\"4\" cy=\"17\" r=\"1\" fill=\"#5c3a17\"/></svg>",
  "elul_b.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M3 18c3-5 6-10 12-11 3-.5 6 1.5 6 4-3.5-1-6 .5-8 3-2 2.5-5 4-10 4z\" fill=\"#c99a5b\" stroke=\"#7c4a1e\" stroke-width=\"1.5\"/><path d=\"M7 11c1-1.5 2.5-2.5 4-3\" stroke=\"#eed8b7\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><circle cx=\"3\" cy=\"18\" r=\"1.2\" fill=\"#4a280d\"/></svg>",
  "elul_shofar_classic.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\" fill=\"none\">\n  <!-- Classic Deeply Curved Ram's Horn Shofar -->\n  <defs>\n    <linearGradient id=\"shofarGrad\" x1=\"15%\" y1=\"85%\" x2=\"85%\" y2=\"20%\">\n      <stop offset=\"0%\" stop-color=\"#42210b\"/>\n      <stop offset=\"25%\" stop-color=\"#784017\"/>\n      <stop offset=\"50%\" stop-color=\"#ad6a28\"/>\n      <stop offset=\"75%\" stop-color=\"#d89b4e\"/>\n      <stop offset=\"90%\" stop-color=\"#fae0ad\"/>\n      <stop offset=\"100%\" stop-color=\"#e4b775\"/>\n    </linearGradient>\n    <linearGradient id=\"shofarBell\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#261204\"/>\n      <stop offset=\"100%\" stop-color=\"#4a2609\"/>\n    </linearGradient>\n  </defs>\n  <!-- Outer horn path: sweeps down into a deep belly curve, curves up into iconic hook with wide flared bell -->\n  <path d=\"M 14 58 C 14 68, 22 86, 38 88 C 56 90, 74 78, 80 60 C 85 45, 87 32, 89 20 C 85 19, 78 22, 73 28 C 71 40, 67 52, 58 60 C 48 70, 36 72, 24 66 C 18 63, 14 57, 14 58 Z\" fill=\"url(#shofarGrad)\" stroke=\"#4a2307\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/>\n  <!-- Flared Bell opening -->\n  <ellipse cx=\"81\" cy=\"24\" rx=\"7.5\" ry=\"12\" transform=\"rotate(35 81 24)\" fill=\"url(#shofarBell)\" stroke=\"#5c2e0b\" stroke-width=\"2\"/>\n  <!-- Mouthpiece tip -->\n  <circle cx=\"14\" cy=\"58\" r=\"3\" fill=\"#2a1303\" stroke=\"#4a2307\" stroke-width=\"1.5\"/>\n  <!-- Transverse natural ridges / rings of the horn -->\n  <path d=\"M 29 84 C 33 78, 32 71, 26 67\" stroke=\"#703c14\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  <path d=\"M 42 84 C 47 77, 45 68, 38 63\" stroke=\"#703c14\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  <path d=\"M 56 79 C 62 71, 59 62, 51 57\" stroke=\"#874b1c\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  <path d=\"M 69 69 C 75 60, 71 49, 63 45\" stroke=\"#9e5c26\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  <path d=\"M 78 54 C 83 45, 79 36, 72 32\" stroke=\"#ba7536\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  <!-- Gloss highlight along outer spine -->\n  <path d=\"M 26 84 C 44 87, 65 80, 75 62 C 81 49, 84 36, 87 22\" stroke=\"#fff1d4\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.55\"/>\n</svg>\n",
  "elul_shofar_dawn.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\" fill=\"none\">\n  <!-- Morning Dawn Sun Rays behind Shofar -->\n  <circle cx=\"50\" cy=\"50\" r=\"38\" fill=\"#fcf6ec\" stroke=\"#e8d3b8\" stroke-width=\"1.5\"/>\n  <path d=\"M50 16 L50 22 M50 78 L50 84 M16 50 L22 50 M78 50 L84 50\" stroke=\"#d4a373\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.7\"/>\n  <!-- Shofar horn resting across center -->\n  <path d=\"M22 68 C 30 64, 38 50, 50 40 C 62 30, 72 26, 82 26 C 85 26, 86 28, 86 31 C 86 39, 78 48, 68 53 C 54 60, 44 62, 32 74 C 26 80, 19 78, 18 73 C 17 70, 19 69, 22 68 Z\" \n        fill=\"#b88646\" stroke=\"#5c3813\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/>\n  <ellipse cx=\"82\" cy=\"34\" rx=\"3.5\" ry=\"8\" fill=\"#3d2105\"/>\n  <circle cx=\"19\" cy=\"71\" r=\"2.5\" fill=\"#3d2105\"/>\n</svg>\n",
  "elul_shofar_silhouette.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\" fill=\"none\">\n  <!-- Clean bold minimalist vector Shofar -->\n  <path d=\"M14 74 C 26 70, 36 52, 50 40 C 64 28, 76 24, 88 24 C 91 24, 92 26, 92 30 C 92 40, 82 52, 70 58 C 54 66, 42 68, 28 82 C 20 89, 11 86, 9 80 C 8 77, 11 75, 14 74 Z\" \n        fill=\"#c99a5b\" stroke=\"#7c4a1e\" stroke-width=\"3\" stroke-linejoin=\"round\"/>\n  <!-- Opening & Mouthpiece -->\n  <ellipse cx=\"88\" cy=\"34\" rx=\"4\" ry=\"10\" fill=\"#7c4a1e\"/>\n  <ellipse cx=\"11\" cy=\"77\" rx=\"3\" ry=\"3\" fill=\"#4a280d\"/>\n  <!-- Polished ridges -->\n  <path d=\"M46 44 C 50 48, 51 55, 47 62\" stroke=\"#ffffff\" stroke-width=\"2.5\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n  <path d=\"M60 34 C 65 39, 66 47, 62 53\" stroke=\"#ffffff\" stroke-width=\"2.5\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n  <path d=\"M74 28 C 79 33, 80 40, 77 46\" stroke=\"#ffffff\" stroke-width=\"2.5\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n</svg>\n",
